-- >>> supabase/sql_src/functions/pseo/city/get_city_airport_route_stats.sql

-- ============================================================================
-- Function: private.get_city_airport_route_stats
-- Feature: Interactive pSEO
-- Purpose: Derive reusable route coverage and airline-model statistics for city airports.
-- Responsibilities: Keep airport-card metrics version-consistent and free of editorial data.
-- Notes: Destination percentages describe distinct destination-city coverage.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.get_city_airport_route_stats(
  p_city_id UUID,
  p_data_version UUID
)
RETURNS TABLE (
  airport_id UUID,
  direct_counterpart_city_count INTEGER,
  domestic_destination_count INTEGER,
  international_destination_count INTEGER,
  domestic_destination_percentage INTEGER,
  international_destination_percentage INTEGER,
  airline_count INTEGER,
  dominant_airline_business_model TEXT
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  WITH city_context AS (
    SELECT city.country_id
    FROM public.cities city
    WHERE city.id = p_city_id
  ),
  airport_routes AS (
    SELECT
      city_route.origin_airport_id AS airport_id,
      city_route.destination_city_id,
      city_route.destination_country_id,
      city_route.operating_airline_id,
      airline.business_model,
      COALESCE(city_route.frequency_per_week, 1) AS business_model_weight
    FROM public.pseo_direct_routes city_route
    JOIN public.airlines airline
      ON airline.id = city_route.operating_airline_id
    WHERE city_route.origin_city_id = p_city_id
      AND city_route.data_version = p_data_version
  ),
  route_stats AS (
    SELECT
      airport_route.airport_id,
      count(DISTINCT airport_route.destination_city_id)::INTEGER AS direct_counterpart_city_count,
      count(DISTINCT airport_route.destination_city_id)
        FILTER (
          WHERE airport_route.destination_country_id = city_context.country_id
        )::INTEGER AS domestic_destination_count,
      count(DISTINCT airport_route.destination_city_id)
        FILTER (
          WHERE airport_route.destination_country_id <> city_context.country_id
        )::INTEGER AS international_destination_count,
      count(DISTINCT airport_route.operating_airline_id)::INTEGER AS airline_count
    FROM airport_routes airport_route
    CROSS JOIN city_context
    GROUP BY airport_route.airport_id
  ),
  business_model_scores AS (
    SELECT
      airport_route.airport_id,
      airport_route.business_model,
      sum(airport_route.business_model_weight) AS score
    FROM airport_routes airport_route
    GROUP BY
      airport_route.airport_id,
      airport_route.business_model
  ),
  dominant_business_models AS (
    SELECT DISTINCT ON (business_model_score.airport_id)
      business_model_score.airport_id,
      business_model_score.business_model
    FROM business_model_scores business_model_score
    ORDER BY
      business_model_score.airport_id,
      business_model_score.score DESC,
      business_model_score.business_model
  )
  SELECT
    airport.id,
    COALESCE(route_stat.direct_counterpart_city_count, 0),
    COALESCE(route_stat.domestic_destination_count, 0),
    COALESCE(route_stat.international_destination_count, 0),
    CASE
      WHEN COALESCE(route_stat.direct_counterpart_city_count, 0) = 0 THEN 0
      ELSE round(
        route_stat.domestic_destination_count::NUMERIC
        * 100
        / route_stat.direct_counterpart_city_count
      )::INTEGER
    END,
    CASE
      WHEN COALESCE(route_stat.direct_counterpart_city_count, 0) = 0 THEN 0
      ELSE round(
        route_stat.international_destination_count::NUMERIC
        * 100
        / route_stat.direct_counterpart_city_count
      )::INTEGER
    END,
    COALESCE(route_stat.airline_count, 0),
    COALESCE(dominant_business_model.business_model, 'unknown')
  FROM public.airports airport
  LEFT JOIN route_stats route_stat
    ON route_stat.airport_id = airport.id
  LEFT JOIN dominant_business_models dominant_business_model
    ON dominant_business_model.airport_id = airport.id
  WHERE airport.city_id = p_city_id
    AND airport.status = 'active';
$$;

REVOKE ALL ON FUNCTION private.get_city_airport_route_stats(UUID, UUID)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.get_city_airport_route_stats(UUID, UUID) TO service_role;

-- >>> supabase/sql_src/functions/pseo/city/get_city_quick_facts.sql

-- ============================================================================
-- Function: private.get_city_quick_facts
-- Feature: Interactive pSEO
-- Purpose: Derive one version-consistent city Quick Facts read model.
-- Responsibilities: Count city coverage and resolve shortest and longest direct destinations.
-- Notes: Route extrema use stored recurring schedules, not live dated availability.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.get_city_quick_facts(
  p_city_id UUID,
  p_data_version UUID
)
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  WITH city_context AS (
    SELECT
      city.id,
      city.slug
    FROM public.cities city
    WHERE city.id = p_city_id
  ),
  routes AS MATERIALIZED (
    SELECT city_route.*
    FROM public.pseo_direct_routes city_route
    WHERE city_route.origin_city_id = p_city_id
      AND city_route.data_version = p_data_version
  ),
  route_counts AS (
    SELECT
      count(DISTINCT route.destination_city_id)::INTEGER AS direct_counterpart_city_count,
      count(DISTINCT route.destination_country_id)::INTEGER AS direct_counterpart_country_count,
      count(DISTINCT route.operating_airline_id)::INTEGER AS airline_count
    FROM routes route
  ),
  shortest_route AS (
    SELECT jsonb_build_object(
      'destination_name', destination_city.name,
      'destination_slug', destination_city.slug,
      'route_path', format(
        '/flights/%s-to-%s',
        city_context.slug,
        destination_city.slug
      ),
      'duration_minutes', route.shortest_duration_minutes
    ) AS value
    FROM routes route
    CROSS JOIN city_context
    JOIN public.cities destination_city
      ON destination_city.id = route.destination_city_id
    ORDER BY
      route.shortest_duration_minutes,
      destination_city.name
    LIMIT 1
  ),
  longest_route AS (
    SELECT jsonb_build_object(
      'destination_name', destination_city.name,
      'destination_slug', destination_city.slug,
      'route_path', format(
        '/flights/%s-to-%s',
        city_context.slug,
        destination_city.slug
      ),
      'duration_minutes', route.longest_duration_minutes
    ) AS value
    FROM routes route
    CROSS JOIN city_context
    JOIN public.cities destination_city
      ON destination_city.id = route.destination_city_id
    ORDER BY
      route.longest_duration_minutes DESC,
      destination_city.name
    LIMIT 1
  )
  SELECT jsonb_build_object(
    'airport_count', (
      SELECT count(*)::INTEGER
      FROM public.airports airport
      WHERE airport.city_id = p_city_id
        AND airport.status = 'active'
    ),
    'direct_counterpart_city_count', route_counts.direct_counterpart_city_count,
    'direct_counterpart_country_count', route_counts.direct_counterpart_country_count,
    'airline_count', route_counts.airline_count,
    'shortest_route', (
      SELECT shortest_route.value
      FROM shortest_route
    ),
    'longest_route', (
      SELECT longest_route.value
      FROM longest_route
    )
  )
  FROM route_counts;
$$;

REVOKE ALL ON FUNCTION private.get_city_quick_facts(UUID, UUID)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.get_city_quick_facts(UUID, UUID) TO service_role;

-- >>> supabase/sql_src/functions/pseo/city/get_city_route_map.sql

-- ============================================================================
-- Function: private.get_city_route_map
-- Feature: Route Map
-- Purpose: Build one version-consistent city-to-city direct-route map read model.
-- Responsibilities: Filter routes, aggregate destination cities, and preserve map geometry.
-- Notes: Destination cities without coordinates are counted but omitted from rendered geometry.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.get_city_route_map(
  p_city_id UUID,
  p_city_slug TEXT,
  p_data_version UUID,
  p_origin_airports TEXT[],
  p_airlines TEXT[],
  p_destination_countries TEXT[],
  p_max_duration_minutes INTEGER,
  p_departure_window TEXT,
  p_limit INTEGER
)
RETURNS JSONB
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  WITH origin AS (
    SELECT
      city.name,
      city.slug,
      city.latitude,
      city.longitude
    FROM public.cities city
    WHERE city.id = p_city_id
  ),
  filtered AS MATERIALIZED (
    SELECT
      city_route.*,
      origin_airport.iata AS origin_airport_iata,
      destination_airport.iata AS destination_airport_iata,
      operating_airline.iata AS operating_airline_iata,
      destination_country.iso2 AS destination_country_iso2,
      destination_country.name AS destination_country_name,
      destination_city.name AS destination_city_name,
      destination_city.slug AS destination_city_slug,
      destination_city.latitude AS destination_city_latitude,
      destination_city.longitude AS destination_city_longitude
    FROM public.pseo_direct_routes city_route
    JOIN public.airports origin_airport
      ON origin_airport.id = city_route.origin_airport_id
    JOIN public.airports destination_airport
      ON destination_airport.id = city_route.destination_airport_id
    JOIN public.airlines operating_airline
      ON operating_airline.id = city_route.operating_airline_id
    JOIN public.countries destination_country
      ON destination_country.id = city_route.destination_country_id
    JOIN public.cities destination_city
      ON destination_city.id = city_route.destination_city_id
    WHERE city_route.origin_city_id = p_city_id
      AND city_route.data_version = p_data_version
      AND (
        cardinality(p_origin_airports) = 0
        OR origin_airport.iata = ANY(p_origin_airports)
      )
      AND (
        cardinality(p_airlines) = 0
        OR operating_airline.iata = ANY(p_airlines)
      )
      AND (
        cardinality(p_destination_countries) = 0
        OR destination_country.iso2 = ANY(p_destination_countries)
      )
      AND (
        p_max_duration_minutes IS NULL
        OR city_route.shortest_duration_minutes <= p_max_duration_minutes
      )
      AND (
        p_departure_window IS NULL
        OR (
          p_departure_window = 'morning'
          AND city_route.earliest_departure_time >= TIME '05:00'
          AND city_route.earliest_departure_time < TIME '12:00'
        )
        OR (
          p_departure_window = 'afternoon'
          AND city_route.earliest_departure_time >= TIME '12:00'
          AND city_route.earliest_departure_time < TIME '17:00'
        )
        OR (
          p_departure_window = 'evening'
          AND city_route.earliest_departure_time >= TIME '17:00'
          AND city_route.earliest_departure_time < TIME '21:00'
        )
        OR (
          p_departure_window = 'night'
          AND (
            city_route.earliest_departure_time >= TIME '21:00'
            OR city_route.earliest_departure_time < TIME '05:00'
          )
        )
      )
  ),
  destinations AS (
    SELECT
      filtered.destination_city_id,
      filtered.destination_city_name,
      filtered.destination_city_slug,
      filtered.destination_country_iso2,
      filtered.destination_country_name,
      filtered.destination_city_latitude,
      filtered.destination_city_longitude,
      jsonb_agg(
        DISTINCT filtered.origin_airport_iata
        ORDER BY filtered.origin_airport_iata
      ) AS origin_airports,
      jsonb_agg(
        DISTINCT filtered.destination_airport_iata
        ORDER BY filtered.destination_airport_iata
      ) AS destination_airports,
      jsonb_agg(
        DISTINCT filtered.operating_airline_iata
        ORDER BY filtered.operating_airline_iata
      ) AS airlines,
      CASE
        WHEN count(filtered.frequency_per_week) = 0 THEN NULL
        ELSE sum(filtered.frequency_per_week)
      END AS frequency_per_week,
      min(filtered.shortest_duration_minutes) AS shortest_duration_minutes,
      min(filtered.confidence_score) AS confidence_score
    FROM filtered
    GROUP BY
      filtered.destination_city_id,
      filtered.destination_city_name,
      filtered.destination_city_slug,
      filtered.destination_country_iso2,
      filtered.destination_country_name,
      filtered.destination_city_latitude,
      filtered.destination_city_longitude
  ),
  ranked AS (
    SELECT destinations.*
    FROM destinations
    WHERE destinations.destination_city_latitude IS NOT NULL
      AND destinations.destination_city_longitude IS NOT NULL
    ORDER BY
      COALESCE(destinations.frequency_per_week, 0) DESC,
      destinations.shortest_duration_minutes,
      destinations.confidence_score DESC,
      destinations.destination_city_name
    LIMIT p_limit
  )
  SELECT jsonb_build_object(
    'origin', (
      SELECT jsonb_build_object(
        'type', 'city',
        'name', origin.name,
        'slug', origin.slug,
        'latitude', origin.latitude,
        'longitude', origin.longitude
      )
      FROM origin
    ),
    'destinations', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'city_name', ranked.destination_city_name,
          'city_slug', ranked.destination_city_slug,
          'country_iso2', ranked.destination_country_iso2,
          'country_name', ranked.destination_country_name,
          'latitude', ranked.destination_city_latitude,
          'longitude', ranked.destination_city_longitude,
          'route_path', format(
            '/flights/%s-to-%s',
            p_city_slug,
            ranked.destination_city_slug
          ),
          'origin_airports', ranked.origin_airports,
          'destination_airports', ranked.destination_airports,
          'airlines', ranked.airlines,
          'shortest_duration_minutes', ranked.shortest_duration_minutes,
          'frequency_per_week', ranked.frequency_per_week
        )
        ORDER BY
          COALESCE(ranked.frequency_per_week, 0) DESC,
          ranked.shortest_duration_minutes,
          ranked.confidence_score DESC,
          ranked.destination_city_name
      )
      FROM ranked
    ), '[]'::JSONB),
    'total', (
      SELECT count(*)::INTEGER
      FROM destinations
    ),
    'omitted_destination_count', (
      SELECT count(*)::INTEGER
      FROM destinations
      WHERE destinations.destination_city_latitude IS NULL
        OR destinations.destination_city_longitude IS NULL
    )
  );
$$;

REVOKE ALL ON FUNCTION private.get_city_route_map(
  UUID,
  TEXT,
  UUID,
  TEXT[],
  TEXT[],
  TEXT[],
  INTEGER,
  TEXT,
  INTEGER
)
FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION private.get_city_route_map(
  UUID,
  TEXT,
  UUID,
  TEXT[],
  TEXT[],
  TEXT[],
  INTEGER,
  TEXT,
  INTEGER
) TO service_role;

